import type { Register, EngineInterface, SessionRateLimit } from 'claude-code'

const LABELS: Record<string, string> = { five_hour: 'セッション', seven_day: '週間' }

function untilReset(resetsAt: string | undefined, now: number) {
  if (resetsAt === undefined) return ''
  const resetMs = Date.parse(resetsAt)
  if (!Number.isFinite(resetMs) || !Number.isFinite(now)) return ''
  const minutes = Math.max(0, Math.round((resetMs - now) / 60000))
  const h = Math.floor(minutes / 60)
  const m = minutes % 60
  return h > 0 ? ` (${h}時間${m}分後)` : ` (${m}分後)`
}

function formatLimit(limit: SessionRateLimit, now: number) {
  const label = LABELS[limit.kind] ?? limit.kind
  return `${label} ${Math.round(limit.percentUsed)}%${untilReset(limit.resetsAt, now)}`
}

async function refresh($: EngineInterface) {
  const { context, rateLimits } = await $.session.usage()
  const now = await $.clock.now()
  const parts = [`ctx 残り ${100 - (context.percent ?? 0)}%`]
  for (const limit of rateLimits) parts.push(formatLimit(limit, now))
  $.ui.status(parts.join(' · '))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await refresh($)
    return result
  })

  on('session.measure', async ($, e, next) => {
    const result = await next(e)
    await refresh($)
    return result
  })

  on('tool.call', async ($, e, next) => {
    const result = await next(e)
    await refresh($)
    return result
  })
}

